struct Account {
    balance: Int
}

enum Op {
    Deposit { amount: Int },
    Withdraw { amount: Int }
}

fn apply(in acc: Account, in op: Op) -> Account {
    match op {
        Deposit { amount: amt } => {
            Account { balance: acc.balance + amt }
        },
        Withdraw { amount: amt } => {
            if acc.balance >= amt {
                Account { balance: acc.balance - amt }
            } else {
                acc // Leave unchanged
            }
        }
    }
}

fn run(in ops: [Op; 4]) -> Int {
    let initial_account = Account { balance: 0 };
    let final_account = foldl(apply, initial_account, ops);
    final_account.balance
}

fn main() {
    let operations: [Op; 4] = [
        Op::Deposit { amount: 100 },
        Op::Withdraw { amount: 30 },
        Op::Withdraw { amount: 200 },
        Op::Deposit { amount: 50 }
    ];
    let final_balance = run(operations);
    print(final_balance);
}

