struct Node {
    value: Int,
    next: Option[Box[Node]]
}

fn list3(a: Int, b: Int, c: Int) -> Node {
    let node_c = Box::new(Node { value: c, next: None });
    let node_b = Box::new(Node { value: b, next: Some(node_c) });
    Box::new(Node { value: a, next: Some(node_b) })
}

fn sum_list(n: Node) -> Int {
    let mut current = n;
    let mut sum = 0;
    loop {
        sum += current.value;
        match current.next {
            Some(next_node) => {
                current = *next_node;
            }
            None => break,
        }
    }
    sum
}

fn length(n: Node) -> Int {
    let mut current = n;
    let mut count = 0;
    loop {
        count += 1;
        match current.next {
            Some(next_node) => {
                current = *next_node;
            }
            None => break,
        }
    }
    count
}

