fn caesar(in s: Str, take k: Int) -> String {
    let len = s.len();
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        let byte = s.get_byte(i).unwrap();

        if (i % 2) == 0 {
            // Even index: apply Caesar cipher shift
            if byte >= 97 && byte <= 122 { // Lowercase ASCII 'a' to 'z'
                let base = 97;
                let offset = (byte - base + k) % 26;
                let new_byte = base + offset;
                result.push(new_byte as u8);
            } else {
                // Non-lowercase ASCII character, copy unchanged
                result.push(byte);
            }
        } else {
            // Odd index: copy unchanged
            result.push(byte);
        }
    }

    String::from_utf8(result).unwrap()
}

