fn collatz_steps(take n: Int) -> Int {
    if n <= 0 {
        panic("Input must be a positive integer")
    }
    if n == 1 {
        return 0
    }

    let mut current = n
    let mut steps = 0

    loop {
        if current == 1 {
            break
        }

        if current % 2 == 0 {
            // Even: n / 2
            current = current / 2
        } else {
            // Odd: 3n + 1
            current = 3 * current + 1
        }
        steps = steps + 1
    }

    steps
}

