fn digits(n: Int) -> Array[Int] {
    if n < 0 {
        panic("Input must be non-negative")
    }
    if n == 0 {
        return [0]
    }

    var digits_list: List[Int] = []
    var temp_n = n
    while temp_n > 0 {
        digits_list.append(temp_n % 10)
        temp_n /= 10
    }

    // The list is currently in reverse order (least significant first).
    // We need to reverse it and convert to Array[Int].
    var result_list: List[Int] = []
    for i in digits_list.size() - 1 downto 0 {
        result_list.append(digits_list[i])
    }

    return result_list.to_array()
}

fn reversed(in xs: Array[Int]) -> Array[Int] {
    var result: Array[Int] = new Array[Int](xs.size())
    for i in range(xs.size()) {
        result[i] = xs[xs.size() - 1 - i]
    }
    return result
}

