fn first_even(xs: [Int; 5]) -> Option[Int] {
    match xs {
        [x, _, _, _, _] if x % 2 == 0 => Some(x),
        [_, y, _, _, _] if y % 2 == 0 => Some(y),
        [_, _, z, _, _] if z % 2 == 0 => Some(z),
        [_, _, _, w, _] if w % 2 == 0 => Some(w),
        [_, _, _, _, v] if v % 2 == 0 => Some(v),
        _ => None,
    }
}

