struct Score {
    student: Int,
    points: Int
}

fn letter(take points: Int) -> Int {
    if points >= 90 {
        return 4;
    } else if points >= 80 {
        return 3;
    } else if points >= 70 {
        return 2;
    } else if points >= 60 {
        return 1;
    } else {
        return 0;
    }
}

fn passing(in scores: [Score; 5]) -> Array[Int] {
    var passing_students: Array[Int] = [];
    for i in 0..5 {
        if letter(scores[i].points) >= 1 {
            passing_students.append(scores[i].student);
        }
    }
    return passing_students;
}

fn class_average(in scores: [Score; 5]) -> Int {
    var total_points: Int = 0;
    for i in 0..5 {
        total_points += scores[i].points;
    }
    return total_points / 5;
}

fn main() {
    let scores: [Score; 5] = [
        {student: 101, points: 95},
        {student: 102, points: 78},
        {student: 103, points: 55},
        {student: 104, points: 82},
        {student: 105, points: 60}
    ];

    let passing_students = passing(scores);
    print("Passing students: ");
    for student in passing_students {
        print(student, " ");
    }
    print("\n");

    let average = class_average(scores);
    print("Class average: ", average);
}

