fn int_sqrt(n: Int) -> Int {
    if n < 0 {
        panic("Input must be non-negative")
    }
    if n == 0 {
        return 0
    }

    // Binary search for the largest r such that r*r <= n
    var low: Int = 1
    // The square root cannot exceed n/2 + 1 for n > 1, but n itself is a safe upper bound
    // Since we are using Int, we must be careful about overflow if n is very large.
    // For standard 32-bit or 64-bit Int, n itself is fine as an upper bound if we check for overflow in the loop condition.
    // A tighter bound is min(n, 2^31 - 1) / 2 + 1, but let's use n+1 as a safe upper bound for the search space,
    // assuming n is within reasonable Int limits where n*n doesn't overflow standard Int multiplication if we check carefully.
    // Since we are looking for r*r <= n, r <= sqrt(n). If n is Int::MAX, r is around sqrt(Int::MAX).
    // Let's use a safe upper bound that won't overflow when squared, e.g., n+1, but we must check for overflow when calculating mid*mid.
    var high: Int = n + 1 // A safe upper bound for the search space of r
    var result: Int = 1

    while low <= high {
        // Calculate mid safely to prevent overflow if low and high are near Int::MAX/2
        let mid = low + (high - low) / 2

        // Check for potential overflow when calculating mid * mid
        // If mid > n/mid (and mid > 0), then mid*mid > n.
        // Since mid >= 1, we can check if mid > n / mid.
        let mid_sq: Int
        if mid == 0 { // Should not happen since low starts at 1
            mid_sq = 0
        } else if mid > n / mid {
            // mid * mid > n, and also mid * mid might overflow if n is close to Int::MAX
            // If mid > n/mid, then mid*mid > n. We treat this as too large.
            mid_sq = n + 1 // A value guaranteed to be > n
        } else {
            mid_sq = mid * mid
        }

        if mid_sq <= n {
            // mid is a potential answer, try for a larger one
            result = mid
            low = mid + 1
        } else {
            // mid*mid > n, too large
            high = mid - 1
        }
    }
    result
}

