enum Token {
    Num { value: Int },
    Add,
    Sub,
    Mul
}

fn eval_rpn(in tokens: [Token; 7]) -> Int {
    var stack: [Int] = []

    for token in tokens {
        match token {
            case .Num(value: let v) => {
                stack.append(v)
            },
            case .Add, .Sub, .Mul => {
                // Pop right operand (op2)
                let op2 = stack.pop_last()
                // Pop left operand (op1)
                let op1 = stack.pop_last()

                let result = match token {
                    .Add => op1 + op2,
                    .Sub => op1 - op2,
                    .Mul => op1 * op2,
                    _ => unreachable!(),
                }
                stack.append(result)
            }
        }
    }

    // Inputs are always well formed, so the result is the single value left on the stack.
    stack.pop_last()
}

