fn rle(in s: Str) -> String {
    if s.len() == 0 {
        return "";
    }

    let mut result = String::new();
    let mut i = 0;

    while i < s.len() {
        let current_char = s[i];
        let mut count = 1;
        let mut j = i + 1;

        while j < s.len() && s[j] == current_char {
            count += 1;
            j += 1;
        }

        result.push(current_char);
        result.push_str(&count.to_string());
        i = j;
    }

    result
}

