fn to_binary(n: Int) -> String {
    if n == 0 {
        return "0".to_string();
    }

    let mut num = n;
    let mut result = String::new();

    while num > 0 {
        let remainder = num % 2;
        let bit = if remainder == 0 { '0' } else { '1' };
        result = format!("{}{}", bit, result);
        num /= 2;
    }

    result
}

