fn build_word_frequency_map(text: Str) -> Map[Str, Int] {
    let mut counts: Map[Str, Int] = Map.empty();
    let words = text.split_by_whitespace();
    for word in words {
        let current_count = counts.get(word).unwrap_or(0);
        counts.insert(word, current_count + 1);
    }
    counts
}

