fn longest_word_length(text: in Str) -> Int {
    let words = text.split_by_whitespace();
    let mut max_len = 0;
    for word in words {
        let len = word.length();
        if len > max_len {
            max_len = len;
        }
    }
    max_len
}

fn count_word(text: in Str, word: in Str) -> Int {
    let word_counts: Map[Str, Int] = build_word_frequency_map(text);
    std::map::get(word_counts, word).unwrap_or(0)
}

fn build_word_frequency_map(text: in Str) -> Map[Str, Int] {
    let mut counts: Map[Str, Int] = Map.empty();
    let words = text.split_by_whitespace();
    for word in words {
        let current_count = std::map::get(counts, word).unwrap_or(0);
        std::map::insert(counts, word, current_count + 1);
    }
    counts
}

